"""Measured K action on the algebra generated by observed log-request fields.

The ordinary requests are never predicted or replaced. Only the fixed linear
primitive is evaluated through measured mixed-product features when a direct
componentwise input test allows it. No optimization or inverse Hessian occurs.
"""
import time
from collections import deque
import numpy as np


def algebra_basis(generators,budget=64,mixed=True):
    W=np.asarray(generators);n=W.shape[0]
    basis=[np.ones(n)/np.sqrt(n)];degrees=[0]
    queue=deque((0,j) for j in range(W.shape[1]));parents=[]
    axis_power=[np.ones(n) for _ in range(W.shape[1])]
    axis_degree=[0 for _ in range(W.shape[1])]
    axis_scale=np.maximum(np.max(np.abs(W),axis=0),1e-300)
    while queue and len(basis)<min(budget,n):
        i,j=queue.popleft()
        if mixed:v=basis[i]*W[:,j];degree=degrees[i]+1
        else:
            axis_power[j]*=W[:,j]/axis_scale[j];axis_degree[j]+=1
            v=axis_power[j].copy();degree=axis_degree[j]
        norm0=np.linalg.norm(v)
        if norm0==0:continue
        v/=norm0;Q=np.column_stack(basis)
        for _ in range(2):v-=Q@(Q.T@v)
        norm=np.linalg.norm(v)
        if norm<1e-10:continue
        v/=norm;index=len(basis);basis.append(v);degrees.append(degree);parents.append((i,j))
        if mixed:queue.extend((index,k) for k in range(W.shape[1]))
        else:queue.append((index,j))
    Q=np.column_stack(basis)
    defects=[]
    for j in range(W.shape[1]):
        X=W[:,j,None]*Q;R=X-Q@(Q.T@X)
        defects.append(float(np.linalg.norm(R)))
    return Q,dict(rank=Q.shape[1],max_degree=max(degrees),closure_defects=defects,
                  closed=bool(max(defects,default=0.)<1e-9))


class AlgebraCarrier:
    def __init__(self,K,budget=64,generator_count=2,training=8,mixed=True,
                 supplied_generators=None,refresh=True):
        self.K=K;self.budget=budget;self.generator_count=generator_count
        self.training=training;self.mixed=mixed;self.supplied=supplied_generators
        self.refresh=refresh;self.anchor=None;self.history=[];self.Q=None;self.Y=None
        self.products=0;self.reuses=0;self.builds=0;self.misses=0;self.events=[]
        self.gamma=8*K.shape[1]*np.finfo(float).eps
        self.rejections=[]

    def build(self,x,out):
        if self.supplied is None:
            logs=np.stack(self.history[-self.training:]);logs-=logs[-1]
            logs-=logs.mean(axis=1)[:,None]
            _,singular,Vt=np.linalg.svd(logs,full_matrices=False)
            count=min(self.generator_count,int(np.sum(singular>max(singular[0],1e-300)*1e-8)))
            W=Vt[:count].T
            if count==0:return
            W=W/np.max(np.abs(W),axis=0)
        else:W=self.supplied
        Q,event=algebra_basis(W,self.budget,self.mixed)
        self.anchor=x.copy();self.base=out.copy();self.Q=Q
        # Constant action is already known from this live product.
        Y=np.ones((len(out),Q.shape[1]))/np.sqrt(len(x))
        if Q.shape[1]>1:
            Y[:,1:]=(self.K@(x[:,None]*Q[:,1:]))/out[:,None]
            self.products+=Q.shape[1]-1
        self.Y=Y;self.builds+=1;self.misses=0
        event.update(generators=W.shape[1],products=self.products)
        self.events.append(event)

    def apply(self,x,tolerance=1e-8):
        self.history.append(np.log(x));self.history=self.history[-self.training:]
        candidate=None
        if self.Q is not None:
            h=np.log(x)-np.log(self.anchor);scale=float(h.max());v=np.exp(h-scale)
            if np.all(v>0):
                c=self.Q.T@v;r=v-self.Q@c;c2=self.Q.T@r;c+=c2;r-=self.Q@c2
                eta=float(np.max(np.abs(r)/v));pred=self.Y@c
                candidate=(pred,scale,eta)
                numerical=self.gamma*(np.abs(self.Y)@np.abs(c)+np.max(np.abs(self.Q),axis=0)@np.abs(c))
                if eta<1 and np.all(pred>numerical):
                    low=(pred-numerical)/(1+eta);high=(pred+numerical)/(1-eta)
                    relative=float(np.max((high-low)/low))
                    if relative<=tolerance:
                        bound=float(np.max(np.log(high/pred))-np.min(np.log(low/pred)))
                        self.reuses+=1
                        return self.base*np.exp(scale)*pred,bound
        out=self.K@x;self.products+=1;self.misses+=1
        if candidate is not None:
            pred,scale,eta=candidate
            actual=out/self.base/np.exp(scale)
            error=float(np.max(np.abs(pred-actual)/actual))
            self.rejections.append(dict(input_relative_residual=eta,output_relative_error=error))
        ready=(len(self.history)>=self.training or self.supplied is not None)
        if ready and (self.Q is None or (self.refresh and self.misses>=self.budget)):
            self.build(x,out)
        return out,0.


def run(K,a,b,passes=256,budget=64,generators=2,training=8,mixed=True,refresh=True):
    start=time.perf_counter()
    left=AlgebraCarrier(K,budget,generators,training,mixed,refresh=refresh)
    right=AlgebraCarrier(K.T,budget,generators,training,mixed,refresh=refresh)
    v=np.ones(len(b));bound=0.
    for _ in range(passes):
        kv,e1=left.apply(v);u=a/kv;u/=u.max()
        ktu,e2=right.apply(u);v=b/ktu;v/=v.max();bound+=e1+e2
    return dict(y=np.log(v),seconds=time.perf_counter()-start,products=left.products+right.products,
        reuses=left.reuses+right.reuses,builds=left.builds+right.builds,bound=bound,
        events=left.events+right.events,rejections=left.rejections+right.rejections)
